def preservar_viagens(apps, schema_editor):
    Viagem=apps.get_model('rotas','Viagem')
    for v in Viagem.objects.all():
        v.ciclo_completo=False
        v.data_servico=django.utils.timezone.localtime(v.iniciada_em).date()
        v.etapa='encerrada' if v.status=='finalizada' else ('transito_volta' if v.sentido=='retorno' else 'transito_ida')
        v.save(update_fields=['ciclo_completo','data_servico','etapa'])


